	'messages:sourceurl' => 'be-tarask:URL-адрас крыніцы:',
	'messages:destfilename' => 'be-tarask:Канчатковая назва файлу:',
	'messages:upload-maxfilesize' => 'be-tarask:Максымальны памер файлу: $1',
